# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: intake
def intake(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs, offset=1):
    return [v + offset for v in xs]

# region: digest
def digest(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: emit
def emit(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: sift
def sift(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return sift(emit(digest(render(intake(shape(raw))))))

